def finding(row):
    fid, name, description, kind, refs, value_kind, required = row
    return {
        "id":fid,"name":name,"description":description,"source_refs":refs,
        "questions":[
            {"id":f"{fid}-q01","text":f"What exact values, codes, references, qualifiers and explicit unknown or data-absent reasons must be recorded for {name.lower()}?","kind":kind,"answer_data":["value or typed reference","code system and version","status and time","explicit unknown or absence reason"]},
            {"id":f"{fid}-q02","text":f"Which person, practitioner, organization, device, source and evidence establishes {name.lower()}, at what clinical, observation and knowledge time, and with what confidence?","kind":"evidence","answer_data":["asserting or observing actor","source and method","evidence and provenance","times","confidence"]},
            {"id":f"{fid}-q03","text":f"How may {name.lower()} be clinically validated, contested, corrected, superseded, retained or disclosed without erasing history or importing a neighboring record lifecycle?","kind":"validation","answer_data":["validation and clinical-review rule","correction route","successor or tombstone","access and retention effect"]},
        ],
        "data_elements":[{"id":f"{fid}-data","name":f"{name} data","description":f"Structured, source-qualified answer data for {name.lower()}.","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":f"{fid}-record","name":f"{name} record","description":f"Versioned evidence-bearing record for {name.lower()} with subject, status, terminology, event and knowledge time, provenance, uncertainty and access marking.","media_or_form":["logical health record","signed or attributable evidence reference"],"serial":True,"identity_strategy":f"Health-context identifier plus {fid} assertion or event identifier; names, dates, codes, file paths and content hashes never identify the person or assertion alone.","source_refs":refs}],
        "inline_only_rationale":None,
    }


def structure():
    return {"bundles":[{"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":[{"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":[finding(item) for item in findings]} for lid,lname,ldescription,lrefs,findings in layers]} for bid,name,description,rationale,refs,layers in BUNDLES]}


